<script setup lang="ts">
import { computed, ref } from 'vue';
import { Head, useForm } from '@inertiajs/vue3';
import AppLayout from '@/layouts/AppLayout.vue';
import type { BreadcrumbItem } from '@/types';

type Post = { id:number; title:string; slug:string; excerpt:string|null; content:string; image:string|null; published_at:string|null; is_published:boolean };
const props = defineProps<{ posts:Post[] }>();
const editing = ref<Post|null>(null);
const showForm = ref(false);
const form = useForm({ title:'', slug:'', excerpt:'', content:'', image:'', published_at:'', is_published:false });
const breadcrumbs:BreadcrumbItem[] = [{ title:'Quản lý Blog', href:'/admin/blog' }];
const isEdit = computed(() => !!editing.value);
function openCreate(){ editing.value=null; form.reset(); form.is_published=false; showForm.value=true; }
function openEdit(post:Post){ editing.value=post; form.title=post.title; form.slug=post.slug; form.excerpt=post.excerpt??''; form.content=post.content; form.image=post.image??''; form.published_at=post.published_at?post.published_at.slice(0,16):''; form.is_published=post.is_published; showForm.value=true; }
function submit(){
    const opts = { onSuccess: () => { showForm.value=false; editing.value=null; form.reset(); } };
    if (editing.value) { form.put(`/admin/blog/${editing.value.id}`, opts); return; }
    form.post('/admin/blog', opts);
}
function remove(post:Post){ if(confirm(`Xóa bài viết "${post.title}"?`)){ useForm({}).delete(`/admin/blog/${post.id}`); } }
</script>
<template><AppLayout :breadcrumbs="breadcrumbs"><Head title="Quản lý Blog"/><div class="min-w-0 flex flex-col gap-4 p-3 sm:p-6 lg:p-8"><div class="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between"><div class="min-w-0"><h1 class="text-xl font-semibold">Quản lý Blog</h1><p class="text-sm text-muted-foreground">Tạo, sửa và xuất bản bài viết.</p></div><button class="w-full rounded-md bg-primary px-4 py-2 text-sm font-medium text-primary-foreground sm:w-auto" @click="openCreate">Thêm bài viết</button></div><div class="overflow-x-auto rounded-lg border"><table class="w-full min-w-[820px] text-sm"><thead><tr class="border-b bg-muted/50 text-left"><th class="p-3">Tiêu đề</th><th class="p-3">Trạng thái</th><th class="p-3">Ngày xuất bản</th><th class="p-3 text-right">Thao tác</th></tr></thead><tbody><tr v-for="post in props.posts" :key="post.id" class="border-b last:border-0"><td class="max-w-[360px] p-3"><div class="truncate font-medium">{{post.title}}</div><div class="truncate text-xs text-muted-foreground">/{{post.slug}}</div></td><td class="p-3">{{post.is_published?'Đã xuất bản':'Bản nháp'}}</td><td class="whitespace-nowrap p-3">{{post.published_at ? new Date(post.published_at).toLocaleString('vi-VN') : '—'}}</td><td class="p-3 text-right"><div class="flex justify-end gap-2"><button class="rounded-md border px-3 py-1.5" @click="openEdit(post)">Sửa</button><button class="rounded-md border px-3 py-1.5 text-destructive" @click="remove(post)">Xóa</button></div></td></tr><tr v-if="!props.posts.length"><td colspan="4" class="p-8 text-center text-muted-foreground">Chưa có bài viết.</td></tr></tbody></table></div><div v-if="showForm" class="fixed inset-0 z-50 overflow-y-auto bg-black/50 p-3 sm:p-6"><div class="mx-auto my-4 w-full max-w-3xl rounded-xl bg-background p-4 shadow-xl sm:my-8 sm:p-6"><div class="mb-4 flex items-start justify-between gap-3"><div class="min-w-0"><h2 class="text-lg font-semibold">{{isEdit?'Sửa bài viết':'Thêm bài viết'}}</h2></div><button class="shrink-0 rounded-md border px-3 py-1.5" @click="showForm=false">Đóng</button></div><form class="grid gap-4" @submit.prevent="submit"><div class="grid gap-4 sm:grid-cols-2"><label class="grid gap-1 text-sm">Tiêu đề<input v-model="form.title" class="min-w-0 rounded-md border px-3 py-2" required maxlength="190"/><span v-if="form.errors.title" class="text-xs text-destructive">{{form.errors.title}}</span></label><label class="grid gap-1 text-sm">Slug<input v-model="form.slug" class="min-w-0 rounded-md border px-3 py-2" maxlength="190"/><span v-if="form.errors.slug" class="text-xs text-destructive">{{form.errors.slug}}</span></label></div><label class="grid gap-1 text-sm">Mô tả ngắn<textarea v-model="form.excerpt" class="min-h-20 min-w-0 rounded-md border px-3 py-2" maxlength="500"/></label><label class="grid gap-1 text-sm">Nội dung<textarea v-model="form.content" class="min-h-60 min-w-0 rounded-md border px-3 py-2" required/></label><label class="grid gap-1 text-sm">Ảnh (URL)<input v-model="form.image" type="url" class="min-w-0 rounded-md border px-3 py-2"/></label><div class="grid gap-4 sm:grid-cols-2"><label class="grid gap-1 text-sm">Ngày xuất bản<input v-model="form.published_at" type="datetime-local" class="min-w-0 rounded-md border px-3 py-2"/></label><label class="flex items-center gap-2 pt-2 text-sm sm:pt-6"><input v-model="form.is_published" type="checkbox"/> Xuất bản</label></div><div class="flex flex-col-reverse gap-2 sm:flex-row sm:justify-end"><button type="button" class="rounded-md border px-4 py-2" @click="showForm=false">Hủy</button><button type="submit" class="rounded-md bg-primary px-4 py-2 text-primary-foreground disabled:opacity-50" :disabled="form.processing">{{form.processing?'Đang lưu...':'Lưu bài viết'}}</button></div></form></div></div></div></AppLayout></template>
